<?php
require_once __DIR__.'/includes/bootstrap.php';require_role(['admin','accueil']);$page_title='Nouveau dépôt';
$expressRate=(float)app_setting('surcharge_express_pct',(string)EXPRESS_SURCHARGE_PERCENT);$clients=db()->query("SELECT id,nom,prenom,telephone,adresse FROM clients WHERE supprime=0 ORDER BY nom LIMIT 500")->fetchAll();$services=db()->query("SELECT t.id AS tarif_id, CONCAT(s.nom, ' · ', ta.nom) AS libelle, t.prix FROM tarifs t JOIN services s ON s.id = t.service_id JOIN types_articles ta ON ta.id = t.type_article_id WHERE s.actif = 1 AND ta.actif = 1 AND t.date_effet = (SELECT MAX(t2.date_effet) FROM tarifs t2 WHERE t2.service_id = t.service_id AND t2.type_article_id = t.type_article_id AND t2.date_effet <= CURRENT_DATE) ORDER BY s.nom, ta.nom")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$client=(int)($_POST['client_id']??0);$type=($_POST['type_depot']??'normal')==='express'?'express':'normal';$modeRemise=($_POST['mode_remise']??'retrait')==='livraison'?'livraison':'retrait';$date=$_POST['date_prevue']??date('Y-m-d');$deliveryAddress=trim($_POST['adresse_livraison']??'');$ids=$_POST['tarif_id']??[];$qty=$_POST['quantite']??[];$descs=$_POST['description']??[];if(!$ids||!$client){flash('Choisissez un client et au moins une prestation.','error');redirect('order_new.php');}
$pdo=db();$pdo->beginTransaction();try{if($modeRemise==='livraison'&&$deliveryAddress===''){$addr=$pdo->prepare('SELECT adresse FROM clients WHERE id=?');$addr->execute([$client]);$deliveryAddress=trim((string)$addr->fetchColumn());}if($modeRemise==='livraison'&&$deliveryAddress==='')throw new RuntimeException('Une adresse de livraison est nécessaire.');$code='PR-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(2)));$pdo->prepare("INSERT INTO commandes(reference,client_id,depose_par,type_depot,mode_remise,date_promise,notes) VALUES(?,?,?,?,?,?,?)")->execute([$code,$client,$_SESSION['user']['id'],$type,$modeRemise,$date,$_POST['notes']??'']);$oid=(int)db_last_insert_id($pdo,'commandes');$ins=$pdo->prepare("INSERT INTO commande_lignes(commande_id,tarif_id,description,quantite) VALUES(?,?,?,?)");foreach($ids as $i=>$sid){if((int)$sid<1)continue;$q=max(1,(int)($qty[$i]??1));$ins->execute([$oid,(int)$sid,trim($descs[$i]??''),$q]);}if($modeRemise==='livraison'){$pdo->prepare("INSERT INTO courses(commande_id,type,date_prevue,adresse) VALUES(?,'livraison',?,?)")->execute([$oid,$date,$deliveryAddress]);}$pdo->commit();flash('Dépôt créé : '.$code);redirect('order_view.php?id='.$oid);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Erreur lors de la création du dépôt.','error');redirect('order_new.php');}}
require 'includes/header.php';?>
<div class="form-card"><form method="post" id="orderForm"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="form-grid"><div class="field"><label>Client *</label><select name="client_id" required><option value="">Sélectionner un client</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>" data-address="<?=e($c['adresse']??'')?>"><?=e($c['prenom'].' '.$c['nom'].' · '.$c['telephone'])?></option><?php endforeach;?></select><?php if(!$clients):?><small>Ajoutez d'abord un client dans le menu Clients.</small><?php endif;?></div><div class="field"><label>Type de dépôt</label><select name="type_depot"><option value="normal">Normal</option><option value="express">Express (+<?=e($expressRate)?>%)</option></select></div><div class="field"><label>Mode de remise</label><select name="mode_remise" data-delivery-mode><option value="retrait">Retrait au pressing</option><option value="livraison">Livraison au client</option></select></div><div class="field" data-delivery-address hidden><label>Adresse de livraison</label><input name="adresse_livraison" placeholder="Adresse complète" autocomplete="street-address"><small>L’adresse enregistrée sur la fiche client est utilisée si ce champ reste vide.</small></div><div class="field"><label>Date prévue</label><input type="date" name="date_prevue" min="<?=date('Y-m-d')?>" value="<?=date('Y-m-d',strtotime('+2 days'))?>" required></div><div class="field"><label>Note interne</label><input name="notes" placeholder="Informations complémentaires"></div></div><hr class="form-divider"><h2>Articles et prestations</h2><p class="muted">Tarifs indicatifs en FCFA. Le dépôt express applique une majoration de <?=e($expressRate)?>%.</p><?php for($i=0;$i<3;$i++):?><div class="form-grid order-line"><div class="field"><label>Prestation</label><select name="tarif_id[]"><option value="">— Aucune —</option><?php foreach($services as $s):?><option value="<?=$s['tarif_id']?>"><?=e($s['libelle'])?> · <?=money($s['prix'])?></option><?php endforeach;?></select></div><div class="field"><label>Quantité</label><input type="number" name="quantite[]" min="1" value="1"></div><div class="field full"><label>Description des vêtements (ex. chemises, pantalons)</label><input name="description[]" placeholder="Description"></div></div><?php endfor;?><button class="btn" type="submit" <?=!$clients||!$services?'disabled':''?>>Créer le dépôt</button> <a class="btn light" href="orders.php">Annuler</a></form></div>
<?php require 'includes/footer.php';?>
